// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testRegression_property() public {
        address alice = address(0x1);
        address bob = address(0x2);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 1 ether);
        vm.prank(alice);
        (bool sent1, ) = address(c).call{value: 1 ether}("");
        require(sent1, "alice deposit failed");
        vm.prank(bob);
        (bool sent2, ) = address(c).call{value: 1 ether}("");
        require(sent2, "bob deposit failed");
        vm.prank(alice);
        c.withdraw();
        vm.prank(bob);
        c.withdraw();
        assertTrue(c.balances(bob) == 0);
    }
}
